import { useCallback, useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import type { ContentFormat, DemoAction, EditorialSettings, ExecutionStatus, IntegrationStatus, ReplyQueueItem, ReplySettings, ThemeRole, TrendCandidate, TrendItem, TrendSettings } from '@threads-id/contracts';
import { GenerationPanel } from './GenerationPanel.js';
import { apiRequest } from './api.js';
import { jakartaDayBoundary, jakartaInputToIso, jakartaInputValue } from './datetime.js';

const dateTime = new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' });
const dateOnly = new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeZone: 'Asia/Jakarta' });
const formatLabels: Record<ContentFormat, string> = { OBSERVASI_PENDEK: 'Observasi pendek', BAHASAN_LEBIH_DALAM: 'Bahasan lebih dalam', TREN_RELEVAN: 'Tren relevan' };
const draftLabels: Record<Draft['status'], string> = { DRAFT: 'Draft', IN_REVIEW: 'Menunggu review', APPROVED: 'Disetujui', SCHEDULED: 'Terjadwal', CANCELLED: 'Dibatalkan' };
const executionLabels: Record<ExecutionStatus, string> = { SIMULATED_OK: 'Simulasi selesai', PUBLISHED: 'Terbit di Threads', SKIPPED_STALE: 'Dilewati · jadwal lama', SKIPPED_CANCELLED: 'Dilewati · dibatalkan', SKIPPED_PAUSED: 'Dilewati · jeda aktif', SKIPPED_LIMIT: 'Dilewati · batas harian', CANCELLED: 'Dibatalkan', FAILED: 'Gagal', NEEDS_REVIEW: 'Perlu rekonsiliasi', DUPLICATE: 'Duplikat · sudah terbit', REQUIRES_LIVE: 'Live belum aktif' };
const publishLabels: Record<string, string> = { QUEUED: 'Antre', CONTAINER_CREATED: 'Container dibuat', PUBLISHED: 'Terbit', NEEDS_REVIEW: 'Perlu rekonsiliasi', FAILED: 'Gagal', DUPLICATE: 'Duplikat', REQUIRES_LIVE: 'Live belum aktif' };
const demoLabels: Record<DemoAction['status'], string> = { QUEUED: 'Antre', PROCESSING: 'Diproses', COMPLETED: 'Selesai', FAILED: 'Gagal' };
const navItems = [{ id: 'dashboard', label: 'Ringkasan', icon: '◫' }, { id: 'editorial', label: 'Tema & Gaya', icon: '✳' }, { id: 'drafts', label: 'Draft', icon: '▤' }, { id: 'review', label: 'Review tren', icon: '◉' }, { id: 'trends', label: 'Tren', icon: '◈' }, { id: 'schedule', label: 'Jadwal', icon: '▦' }, { id: 'publish', label: 'Publikasi', icon: '▶' }, { id: 'history', label: 'Riwayat', icon: '↗' }, { id: 'integrations', label: 'Integrasi', icon: '⌘' }] as const;
type View = typeof navItems[number]['id'];
type Theme = { id: string; name: string; role: ThemeRole; weight: number; active: boolean; examples: string[]; createdAt: string; updatedAt: string };
type VoiceExample = { id: string; text: string; createdAt: string };
type PersonalSource = { id: string; note: string; createdAt: string };
type ReviewTopic = { id: string; topic: string; status: 'OPEN' | 'RESOLVED'; createdAt: string; updatedAt: string };
type Draft = { id: string; themeId: string; themeName: string; format: ContentFormat; text: string; status: 'DRAFT' | 'IN_REVIEW' | 'APPROVED' | 'SCHEDULED' | 'CANCELLED'; locked: boolean; sourceUrl: string | null; sourceTime: string | null; relevanceNote: string | null; personalSourceId: string | null; reviewNote: string | null; version: number; createdAt: string; updatedAt: string };
type ScheduleEntry = { id: string; draftId: string; draftText: string; themeName: string; format: ContentFormat; scheduledAt: string; status: 'SCHEDULED' | 'COMPLETED' | 'CANCELLED'; version: number; createdAt: string; updatedAt: string };
type HistoryItem = { id: string; scheduleId: string; draftId: string | null; draftText: string | null; themeId: string | null; themeName: string | null; format: ContentFormat | null; draftStatus: string | null; scheduledAt: string | null; executedAt: string; snapshotProvenance: string; status: ExecutionStatus; version: number; result: Record<string, unknown> | null; error: string | null; demo: boolean };
type ConnectionStatus = { appId: string | null; appSecretPresent: boolean; userId: string | null; accessTokenPresent: boolean; tokenExpiresAt: string | null; scopes: string | null; status: string; livePosting: boolean; note: string | null };
type PublishQueueItem = { id: string; draftId: string; scheduleId: string | null; trigger: 'MANUAL' | 'SCHEDULED'; status: 'QUEUED' | 'CONTAINER_CREATED' | 'PUBLISHED' | 'NEEDS_REVIEW' | 'FAILED' | 'DUPLICATE' | 'REQUIRES_LIVE'; containerId: string | null; mediaId: string | null; publishedUrl: string | null; attemptCount: number; lastErrorCode: string | null; lastError: string | null; requestedBy: string | null; createdAt: string; updatedAt: string };
type AuthSession = { authenticated: boolean; username?: string };
type ThemeForm = { name: string; role: ThemeRole; examples: string; active: boolean };
type DraftForm = { themeId: string; format: ContentFormat; text: string; sourceUrl: string; sourceTime: string; relevanceNote: string; personalSourceId: string };
type HistoryFilters = { status: string; themeId: string; format: string; from: string; to: string };
type TrendRun = { id: string; status: string; result: Record<string, unknown> | null; createdAt: string; updatedAt: string };
const emptyDraft: DraftForm = { themeId: '', format: 'OBSERVASI_PENDEK', text: '', sourceUrl: '', sourceTime: '', relevanceNote: '', personalSourceId: '' };
const emptyTheme: ThemeForm = { name: '', role: 'UTAMA', examples: '', active: true };
const emptyHistoryFilters: HistoryFilters = { status: '', themeId: '', format: '', from: '', to: '' };
function formatDate(value: string | null | undefined): string { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : dateTime.format(date); }
function splitExamples(value: string): string[] { return value.split('\n').map((line) => line.trim()).filter(Boolean); }
function errorMessage(error: unknown): string { return error instanceof Error ? error.message : 'Terjadi kesalahan. Coba lagi.'; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span className="field-label">{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Panel({ title, description, actions, children, className = '' }: { title: string; description?: string; actions?: ReactNode; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{actions}</div>{children}</section>; }
function Empty({ children }: { children: ReactNode }) { return <div className="empty-state">{children}</div>; }
function Status({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'good' | 'warn' | 'bad' | 'sim' }) { return <span className={`status-pill ${tone}`}>{children}</span>; }

export function App() {
  const [authState, setAuthState] = useState<'checking' | 'signedOut' | 'signedIn'>('checking');
  const [username, setUsername] = useState(''); const [loginName, setLoginName] = useState(''); const [loginPassword, setLoginPassword] = useState(''); const [loginBusy, setLoginBusy] = useState(false);
  const [view, setView] = useState<View>('dashboard'); const [busy, setBusy] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const [themes, setThemes] = useState<Theme[]>([]); const [settings, setSettings] = useState<EditorialSettings | null>(null); const [voices, setVoices] = useState<VoiceExample[]>([]); const [personalSources, setPersonalSources] = useState<PersonalSource[]>([]); const [topics, setTopics] = useState<ReviewTopic[]>([]); const [drafts, setDrafts] = useState<Draft[]>([]); const [schedules, setSchedules] = useState<ScheduleEntry[]>([]); const [history, setHistory] = useState<HistoryItem[]>([]);  const [integrations, setIntegrations] = useState<IntegrationStatus | null>(null); const [demoActions, setDemoActions] = useState<DemoAction[]>([]);
  const [connection, setConnection] = useState<ConnectionStatus | null>(null); const [publishQueue, setPublishQueue] = useState<PublishQueueItem[]>([]); const [publishDraftId, setPublishDraftId] = useState(''); const [publishBusy, setPublishBusy] = useState(false);
  const [trendSettings, setTrendSettings] = useState<TrendSettings | null>(null); const [trendItems, setTrendItems] = useState<TrendItem[]>([]); const [trendCandidates, setTrendCandidates] = useState<TrendCandidate[]>([]); const [trendRun, setTrendRun] = useState<TrendRun | null>(null); const [trendBusy, setTrendBusy] = useState(false);
  const [replySettings, setReplySettings] = useState<ReplySettings | null>(null); const [replyQueue, setReplyQueue] = useState<ReplyQueueItem[]>([]); const [replyToId, setReplyToId] = useState(''); const [replyText, setReplyText] = useState(''); const [replyBusy, setReplyBusy] = useState(false);
  const [weightsDraft, setWeightsDraft] = useState<Record<string, string>>({}); const [themeForm, setThemeForm] = useState<ThemeForm>(emptyTheme); const [editingThemeId, setEditingThemeId] = useState<string | null>(null);
  const [voiceText, setVoiceText] = useState(''); const [personalNote, setPersonalNote] = useState(''); const [topicText, setTopicText] = useState(''); const [draftForm, setDraftForm] = useState<DraftForm>(emptyDraft); const [editingDraft, setEditingDraft] = useState<Draft | null>(null);
  const [reviewNotes, setReviewNotes] = useState<Record<string, string>>({}); const [scheduleDraftId, setScheduleDraftId] = useState(''); const [scheduleTime, setScheduleTime] = useState(''); const [historyFilters, setHistoryFilters] = useState<HistoryFilters>(emptyHistoryFilters); const [historyLoading, setHistoryLoading] = useState(false); const [demoBusy, setDemoBusy] = useState(false);

  const loadAll = useCallback(async () => {
    setBusy(true);
    try {
      const [nextThemes, nextSettings, nextVoices, nextSources, nextTopics, nextDrafts, nextSchedules, nextHistory, nextIntegrations, nextDemo, nextConnection, nextPublish, nextTrendSettings, nextTrendItems, nextTrendCandidates, nextReplySettings, nextReplyQueue] = await Promise.all([
        apiRequest<Theme[]>('/api/themes'), apiRequest<EditorialSettings>('/api/settings'), apiRequest<VoiceExample[]>('/api/voice-examples'), apiRequest<PersonalSource[]>('/api/personal-sources'), apiRequest<ReviewTopic[]>('/api/review-topics'), apiRequest<Draft[]>('/api/drafts'), apiRequest<ScheduleEntry[]>('/api/schedule'), apiRequest<HistoryItem[]>('/api/history'), apiRequest<IntegrationStatus>('/api/integrations'), apiRequest<DemoAction[]>('/api/demo/actions'), apiRequest<ConnectionStatus>('/api/threads/connection'), apiRequest<PublishQueueItem[]>('/api/threads/publish'), apiRequest<TrendSettings>('/api/trends/settings'), apiRequest<TrendItem[]>('/api/trends/items'), apiRequest<TrendCandidate[]>('/api/trends/candidates'), apiRequest<ReplySettings>('/api/threads/replies/settings'), apiRequest<ReplyQueueItem[]>('/api/threads/replies')
      ]);
      setThemes(nextThemes); setSettings(nextSettings); setVoices(nextVoices); setPersonalSources(nextSources); setTopics(nextTopics); setDrafts(nextDrafts); setSchedules(nextSchedules); setHistory(nextHistory); setIntegrations(nextIntegrations); setDemoActions(nextDemo); setConnection(nextConnection); setPublishQueue(nextPublish); setTrendSettings(nextTrendSettings); setTrendItems(nextTrendItems); setTrendCandidates(nextTrendCandidates); setReplySettings(nextReplySettings); setReplyQueue(nextReplyQueue);
      setWeightsDraft(Object.fromEntries(nextThemes.map((theme) => [theme.id, String(theme.weight)])));
      setDraftForm((form) => ({ ...form, themeId: form.themeId || nextThemes[0]?.id || '' }));
      setScheduleDraftId((current) => current || nextDrafts.find((draft) => ['DRAFT', 'APPROVED'].includes(draft.status))?.id || ''); setError('');
    } catch (cause) { setError(errorMessage(cause)); } finally { setBusy(false); }
  }, []);

  useEffect(() => {
    let active = true;
    apiRequest<AuthSession>('/api/auth/session').then(async (session) => { if (!active) return; if (session.authenticated) { setUsername(session.username ?? 'admin'); setAuthState('signedIn'); await loadAll(); } else setAuthState('signedOut'); }).catch(() => { if (active) setAuthState('signedOut'); });
    return () => { active = false; };
  }, [loadAll]);
  useEffect(() => { if (authState !== 'signedIn') return undefined; const timer = window.setInterval(() => { apiRequest<DemoAction[]>('/api/demo/actions').then(setDemoActions).catch(() => undefined); }, 2000); return () => window.clearInterval(timer); }, [authState]);

  const openReviews = useMemo(() => drafts.filter((draft) => draft.status === 'IN_REVIEW'), [drafts]);
  const activeSchedules = useMemo(() => schedules.filter((entry) => entry.status === 'SCHEDULED'), [schedules]);
  const eligibleDrafts = useMemo(() => drafts.filter((draft) => ['DRAFT', 'APPROVED'].includes(draft.status)), [drafts]);
  const weightTotal = themes.reduce((total, theme) => total + (Number(weightsDraft[theme.id]) || 0), 0);

  const mutate = async (operation: () => Promise<unknown>, success?: string) => {
    setSaving(true); setError(''); setNotice('');
    try { await operation(); if (success) setNotice(success); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } finally { setSaving(false); }
  };
  const login = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setLoginBusy(true); setError(''); try { const session = await apiRequest<{ username: string }>('/api/auth/login', { method: 'POST', body: { username: loginName.trim(), password: loginPassword } }); setUsername(session.username); setLoginPassword(''); setAuthState('signedIn'); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } finally { setLoginBusy(false); } };
  const logout = async () => { setSaving(true); setError(''); try { await apiRequest('/api/auth/logout', { method: 'POST', body: {} }); setAuthState('signedOut'); setUsername(''); setThemes([]); setDrafts([]); setSchedules([]); setHistory([]); setNotice('Anda sudah keluar.'); } catch (cause) { setError(errorMessage(cause)); } finally { setSaving(false); } };
  const saveTheme = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const examples = splitExamples(themeForm.examples); if (!examples.length) { setError('Tambahkan minimal satu contoh tulisan.'); return; } const payload = { name: themeForm.name.trim(), role: themeForm.role, examples, active: themeForm.active }; await mutate(async () => { if (editingThemeId) await apiRequest(`/api/themes/${editingThemeId}`, { method: 'PATCH', body: payload }); else await apiRequest('/api/themes', { method: 'POST', body: { ...payload, weight: 0 } }); setThemeForm(emptyTheme); setEditingThemeId(null); }, editingThemeId ? 'Tema berhasil diperbarui.' : 'Tema baru ditambahkan dengan bobot 0%; atur ulang bobot agar totalnya 100%.'); };
  const editTheme = (theme: Theme) => { setEditingThemeId(theme.id); setThemeForm({ name: theme.name, role: theme.role, examples: theme.examples.join('\n'), active: theme.active }); document.getElementById('theme-editor')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); };
  const saveWeights = async () => { const weights = themes.map((theme) => ({ id: theme.id, weight: Number(weightsDraft[theme.id]) })); if (weights.some((entry) => !Number.isInteger(entry.weight) || entry.weight < 0 || entry.weight > 100) || weights.reduce((sum, entry) => sum + entry.weight, 0) !== 100) { setError('Bobot tema harus berupa bilangan bulat dan total tepat 100%.'); return; } await mutate(() => apiRequest('/api/themes/weights', { method: 'PUT', body: { weights } }), 'Bobot seluruh tema berhasil disimpan.'); };
  const saveSettings = async () => { if (settings) await mutate(() => apiRequest('/api/settings', { method: 'PATCH', body: settings }), 'Pengaturan publikasi berhasil disimpan.'); };
  const addVoice = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (voiceText.trim()) await mutate(async () => { await apiRequest('/api/voice-examples', { method: 'POST', body: { text: voiceText.trim() } }); setVoiceText(''); }, 'Contoh suara ditambahkan.'); };
  const addPersonalSource = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (personalNote.trim()) await mutate(async () => { await apiRequest('/api/personal-sources', { method: 'POST', body: { note: personalNote.trim() } }); setPersonalNote(''); }, 'Catatan pemilik tersimpan.'); };
  const addTopic = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (topicText.trim()) await mutate(async () => { await apiRequest('/api/review-topics', { method: 'POST', body: { topic: topicText.trim() } }); setTopicText(''); }, 'Topik review ditambahkan.'); };
  const submitDraft = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const data = { themeId: draftForm.themeId, format: draftForm.format, text: draftForm.text.trim(), sourceUrl: draftForm.sourceUrl.trim() || null, sourceTime: draftForm.sourceTime ? jakartaInputToIso(draftForm.sourceTime) : null, relevanceNote: draftForm.relevanceNote.trim() || null, personalSourceId: draftForm.personalSourceId || null };
    if (!data.text || !data.themeId) { setError('Pilih tema dan isi teks draft.'); return; }
    await mutate(async () => { if (editingDraft) await apiRequest(`/api/drafts/${editingDraft.id}`, { method: 'PATCH', body: { ...data, expectedVersion: editingDraft.version } }); else await apiRequest('/api/drafts', { method: 'POST', body: data }); setDraftForm({ ...emptyDraft, themeId: themes[0]?.id ?? '' }); setEditingDraft(null); }, editingDraft ? 'Perubahan draft tersimpan.' : (draftForm.format === 'TREN_RELEVAN' ? 'Draft tren masuk antrean review.' : 'Draft berhasil dibuat.'));
  };
  const editDraft = (draft: Draft) => { setEditingDraft(draft); setDraftForm({ themeId: draft.themeId, format: draft.format, text: draft.text, sourceUrl: draft.sourceUrl ?? '', sourceTime: jakartaInputValue(draft.sourceTime), relevanceNote: draft.relevanceNote ?? '', personalSourceId: draft.personalSourceId ?? '' }); setView('drafts'); window.setTimeout(() => document.getElementById('draft-editor')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0); };
  const submitSchedule = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { const scheduledAt = jakartaInputToIso(scheduleTime); await mutate(() => apiRequest('/api/schedule', { method: 'POST', body: { draftId: scheduleDraftId, scheduledAt } }), 'Jadwal simulasi berhasil dibuat.'); setScheduleTime(''); } catch (cause) { setError(errorMessage(cause)); } };
  const loadHistory = async (event?: FormEvent<HTMLFormElement>) => { event?.preventDefault(); setHistoryLoading(true); setError(''); try { const params = new URLSearchParams(); if (historyFilters.status) params.set('status', historyFilters.status); if (historyFilters.themeId) params.set('themeId', historyFilters.themeId); if (historyFilters.format) params.set('format', historyFilters.format); const from = jakartaDayBoundary(historyFilters.from); const to = jakartaDayBoundary(historyFilters.to, true); if (from) params.set('from', from); if (to) params.set('to', to); setHistory(await apiRequest<HistoryItem[]>(`/api/history${params.size ? `?${params.toString()}` : ''}`)); } catch (cause) { setError(errorMessage(cause)); } finally { setHistoryLoading(false); } };
  const runDemo = async () => { setDemoBusy(true); setError(''); setNotice(''); try { await apiRequest('/api/demo/actions', { method: 'POST', body: {} }); setDemoActions(await apiRequest<DemoAction[]>('/api/demo/actions')); setNotice('Simulasi dimasukkan ke antrean lokal. Tidak ada konten yang dipublikasikan.'); } catch (cause) { setError(errorMessage(cause)); } finally { setDemoBusy(false); } };
  const openOAuth = async () => { try { const { url } = await apiRequest<{ url: string }>('/api/threads/oauth-url'); window.open(url, '_blank', 'noopener'); setNotice('Lengkapi OAuth Meta di tab baru, lalu klik Hubungkan akun.'); } catch (cause) { setError(errorMessage(cause)); } };
  const connectAccount = async () => { const code = window.prompt('Tempel code dari halaman OAuth Meta (bukan token):'); if (!code) return; try { const result = await apiRequest<{ ok: boolean; userId: string | null }>('/api/threads/oauth-callback', { method: 'POST', body: { code: code.trim() } }); setNotice(`Akun ${result.userId ?? 'Meta'} terhubung. Token disimpan server; dashboard tidak menampilkannya.`); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } };
  const toggleLive = async (livePosting: boolean) => { if (livePosting && !window.confirm('Aktifkan publikasi LIVE ke Meta Threads? Posting akan benar-benar terbit.')) return; try { await apiRequest('/api/threads/live', { method: 'POST', body: { livePosting } }); setNotice(livePosting ? 'Publikasi live diaktifkan. Jadwal berikutnya masuk antrean Meta.' : 'Publikasi live dimatikan; eksekusi kembali simulasi.'); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } };
  const submitManualPublish = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!publishDraftId) { setError('Pilih draft untuk diposting.'); return; } setPublishBusy(true); setError(''); setNotice(''); try { const result = await apiRequest<{ queue: PublishQueueItem; liveEnabled: boolean }>('/api/threads/publish', { method: 'POST', body: { draftId: publishDraftId } }); if (!result.liveEnabled) { setNotice('Live belum aktif: antrean dicatat, tidak ada post nyata. Aktifkan live di Integrasi.'); } else { setNotice('Draft masuk antrean publish Meta. Pantau status di panel ini.'); } await loadAll(); } catch (cause) { setError(errorMessage(cause)); } finally { setPublishBusy(false); } };
  const resolveQueue = async (item: PublishQueueItem, resolution: 'PUBLISHED' | 'FAILED') => { if (resolution === 'PUBLISHED' && !window.confirm('Tandai sudah terbit? Pastikan kamu mengecek akun Threads.')) return; try { await apiRequest(`/api/threads/publish/${item.id}/resolve`, { method: 'POST', body: { resolution } }); setNotice(resolution === 'PUBLISHED' ? 'Antrean ditandai terbit.' : 'Antrean ditandai gagal; tidak ada kirim ulang otomatis.'); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } };
  const refreshTrends = async () => { setTrendBusy(true); setError(''); setNotice(''); try { const { runId } = await apiRequest<{ runId: string }>('/api/trends/refresh', { method: 'POST', body: {} }); setNotice('Discovery tren dimasukkan ke antrean worker; hasil muncul setelah selesai.'); setTrendRun(await apiRequest<TrendRun>(`/api/trends/runs/${runId}`)); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } finally { setTrendBusy(false); } };
  const saveTrendSettings = async () => { if (trendSettings) await mutate(() => apiRequest('/api/trends/settings', { method: 'PATCH', body: trendSettings }), 'Pengaturan tren tersimpan.'); };
  const dismissTrendCandidate = async (id: string) => { await mutate(() => apiRequest(`/api/trends/candidates/${id}/dismiss`, { method: 'POST', body: {} }), 'Kandidat tren dibuang.'); };
  const toggleReplyLive = async (live: boolean) => { if (live && !window.confirm('Aktifkan LIVE balasan ke Meta Threads? Balasan akan benar-benar terkirim.')) return; await mutate(() => apiRequest('/api/threads/replies/settings', { method: 'PATCH', body: { livePosting: live, paused: replySettings?.paused ?? false, dailyLimit: replySettings?.dailyLimit ?? 20 } }), live ? 'Live balasan diaktifkan.' : 'Live balasan dimatikan.'); };
  const toggleReplyPaused = async () => { await mutate(() => apiRequest('/api/threads/replies/settings', { method: 'PATCH', body: { livePosting: replySettings?.livePosting ?? false, paused: !(replySettings?.paused ?? false), dailyLimit: replySettings?.dailyLimit ?? 20 } }), 'Status jeda balasan diperbarui.'); };
  const submitReply = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setReplyBusy(true); setError(''); setNotice(''); try { const result = await apiRequest<{ reply: ReplyQueueItem; liveEnabled: boolean }>('/api/threads/replies', { method: 'POST', body: { replyToId: replyToId.trim(), text: replyText.trim() } }); setNotice(result.liveEnabled ? 'Balasan masuk antrean Meta.' : 'Live balasan mati: antrean dicatat, tidak ada balasan nyata.'); setReplyText(''); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } finally { setReplyBusy(false); } };
  const resolveReply = async (item: ReplyQueueItem, resolution: 'REPLIED' | 'FAILED') => { if (resolution === 'REPLIED' && !window.confirm('Tandai sudah terbalas? Pastikan kamu mengecek akun Threads.')) return; try { await apiRequest(`/api/threads/replies/${item.id}/resolve`, { method: 'POST', body: { resolution } }); setNotice(resolution === 'REPLIED' ? 'Balasan ditandai terbalas.' : 'Balasan ditandai gagal.'); await loadAll(); } catch (cause) { setError(errorMessage(cause)); } };

  if (authState === 'checking') return <main className="auth-shell"><div className="auth-card"><span className="brand-mark">t.</span><p>Memeriksa sesi admin…</p></div></main>;
  if (authState === 'signedOut') return <main className="auth-shell"><div className="auth-card"><span className="brand-mark">t.</span><p className="eyebrow">DASHBOARD EDITORIAL · SIMULASI</p><h1>Masuk ke ruang kerja</h1><p className="muted">Kelola draft dan jadwal simulasi Threads Indonesia. Tidak ada publikasi live di fase ini.</p>{error && <div className="alert error" role="alert">{error}</div>}<form data-testid="login-form" className="stack-form" onSubmit={(event) => void login(event)}><Field label="Username"><input data-testid="login-username" autoComplete="username" value={loginName} onChange={(event) => setLoginName(event.target.value)} required /></Field><Field label="Password"><input data-testid="login-password" type="password" autoComplete="current-password" value={loginPassword} onChange={(event) => setLoginPassword(event.target.value)} required /></Field><button data-testid="login-submit" className="button primary full" disabled={loginBusy}>{loginBusy ? 'Memeriksa…' : 'Masuk'}</button></form><p className="auth-footnote">Gunakan akun admin yang dikonfigurasi lokal. Tidak ada kredensial demo yang ditanam di dashboard.</p></div></main>;

  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href="#dashboard" onClick={(event) => { event.preventDefault(); setView('dashboard'); }}><span className="brand-mark">t.</span><span><strong>threads</strong><small>INDONESIA STUDIO</small></span></a><div className="workspace-label">RUANG KERJA</div><nav aria-label="Navigasi utama">{navItems.map((item) => <button data-testid={`nav-${item.id}`} key={item.id} className={`nav-link ${view === item.id ? 'selected' : ''}`} onClick={() => setView(item.id)}><span className="nav-icon">{item.icon}</span><span>{item.label}</span>{item.id === 'review' && openReviews.length > 0 && <span className="nav-count">{openReviews.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="mode-card"><span className="pulse-dot" /><div><strong>Mode simulasi</strong><small>Publikasi live nonaktif</small></div></div><button data-testid="logout" className="nav-link logout-link" onClick={() => void logout()} disabled={saving}><span className="nav-icon">↪</span><span>Keluar</span></button></div></aside>
    <main className="main-area"><header className="topbar"><div className="breadcrumb"><span>Studio</span><b>/</b><strong>{navItems.find((item) => item.id === view)?.label}</strong></div><div className="top-actions"><span className="timezone-label">Asia/Jakarta <b>UTC+7</b></span><button className="icon-button" aria-label="Muat ulang data" title="Muat ulang data" onClick={() => void loadAll()} disabled={busy}>↻</button><div className="avatar" aria-label={`Admin ${username}`}>{username.slice(0, 1).toUpperCase()}</div></div></header><div className="page-content">
      {(error || notice) && <div className={`alert ${error ? 'error' : 'success'}`} role={error ? 'alert' : 'status'}><span>{error || notice}</span><button aria-label="Tutup pesan" onClick={() => { setError(''); setNotice(''); }}>×</button></div>}{busy && <div className="loading-line"><span /> Memuat data terbaru…</div>}
      {view === 'dashboard' && <DashboardView themes={themes} drafts={drafts} reviews={openReviews} schedules={activeSchedules} history={history} integrations={integrations} formatMix={settings?.formatMix} demoActions={demoActions} demoBusy={demoBusy} onRunDemo={() => void runDemo()} onNavigate={setView} />}
      {view === 'drafts' && <GenerationPanel themes={themes} drafts={drafts} sources={personalSources} onChanged={loadAll} />}
      {view === 'editorial' && <EditorialView themes={themes} weightsDraft={weightsDraft} weightTotal={weightTotal} themeForm={themeForm} editingThemeId={editingThemeId} settings={settings} voices={voices} personalSources={personalSources} topics={topics} saving={saving} voiceText={voiceText} personalNote={personalNote} topicText={topicText} onThemeForm={setThemeForm} onSaveTheme={(event) => void saveTheme(event)} onEditTheme={editTheme} onCancelTheme={() => { setEditingThemeId(null); setThemeForm(emptyTheme); }} onWeightChange={(id, value) => setWeightsDraft((current) => ({ ...current, [id]: value }))} onSaveWeights={() => void saveWeights()} onSettingsChange={setSettings} onSaveSettings={() => void saveSettings()} onVoiceText={setVoiceText} onAddVoice={(event) => void addVoice(event)} onDeleteVoice={(id) => void mutate(() => apiRequest(`/api/voice-examples/${id}`, { method: 'DELETE' }), 'Contoh suara dihapus.')} onPersonalNote={setPersonalNote} onAddPersonal={(event) => void addPersonalSource(event)} onDeletePersonal={(id) => void mutate(() => apiRequest(`/api/personal-sources/${id}`, { method: 'DELETE' }), 'Catatan pemilik dihapus.')} onTopicText={setTopicText} onAddTopic={(event) => void addTopic(event)} onTopicStatus={(topic) => void mutate(() => apiRequest(`/api/review-topics/${topic.id}`, { method: 'PATCH', body: { status: topic.status === 'OPEN' ? 'RESOLVED' : 'OPEN' } }), 'Status topik diperbarui.')} />}
      {view === 'drafts' && <DraftsView themes={themes} drafts={drafts} personalSources={personalSources} form={draftForm} editing={editingDraft} saving={saving} onForm={setDraftForm} onSubmit={(event) => void submitDraft(event)} onEdit={editDraft} onCancelEdit={() => { setEditingDraft(null); setDraftForm({ ...emptyDraft, themeId: themes[0]?.id ?? '' }); }} onLock={(draft) => void mutate(() => apiRequest(`/api/drafts/${draft.id}/lock`, { method: 'POST', body: { locked: !draft.locked } }), draft.locked ? 'Draft dibuka.' : 'Draft dikunci.')} />}
      {view === 'review' && <ReviewView drafts={openReviews} notes={reviewNotes} saving={saving} onNote={(id, value) => setReviewNotes((current) => ({ ...current, [id]: value }))} onDecision={(draft, decision) => void mutate(async () => { await apiRequest(`/api/drafts/${draft.id}/review`, { method: 'POST', body: { decision, note: reviewNotes[draft.id]?.trim() || undefined } }); setReviewNotes((current) => ({ ...current, [draft.id]: '' })); }, decision === 'APPROVE' ? 'Draft tren disetujui.' : 'Draft tren dikembalikan ke draft biasa.')} onEdit={editDraft} onLock={(draft) => void mutate(() => apiRequest(`/api/drafts/${draft.id}/lock`, { method: 'POST', body: { locked: !draft.locked } }), draft.locked ? 'Draft dibuka.' : 'Draft dikunci.')} />}
      {view === 'trends' && <TrendsView settings={trendSettings} items={trendItems} candidates={trendCandidates} run={trendRun} busy={trendBusy} saving={saving} onRefresh={() => void refreshTrends()} onSettings={setTrendSettings} onSaveSettings={() => void saveTrendSettings()} onDismiss={(id) => void dismissTrendCandidate(id)} />}
      {view === 'schedule' && <ScheduleView schedules={schedules} eligibleDrafts={eligibleDrafts} draftId={scheduleDraftId} scheduledAt={scheduleTime} saving={saving} onDraftId={setScheduleDraftId} onScheduledAt={setScheduleTime} onSubmit={(event) => void submitSchedule(event)} onReschedule={(entry, value) => { try { void mutate(() => apiRequest(`/api/schedule/${entry.id}`, { method: 'PATCH', body: { scheduledAt: jakartaInputToIso(value) } }), 'Jadwal diperbarui.'); } catch (cause) { setError(errorMessage(cause)); } }} onCancel={(entry) => { if (window.confirm('Batalkan jadwal ini?')) void mutate(() => apiRequest(`/api/schedule/${entry.id}/cancel`, { method: 'POST', body: {} }), 'Jadwal dibatalkan.'); }} />}
      {view === 'history' && <HistoryView items={history} themes={themes} filters={historyFilters} loading={historyLoading} onFilterChange={setHistoryFilters} onSubmit={(event) => void loadHistory(event)} onReset={() => { setHistoryFilters(emptyHistoryFilters); void apiRequest<HistoryItem[]>('/api/history').then(setHistory).catch((cause: unknown) => setError(errorMessage(cause))); }} />}
      {view === 'integrations' && <IntegrationsView integrations={integrations} />}
      {view === 'publish' && <ThreadsPublishView connection={connection} publishQueue={publishQueue} drafts={drafts} publishDraftId={publishDraftId} publishBusy={publishBusy} onPublishDraftId={setPublishDraftId} onSubmitPublish={(event) => void submitManualPublish(event)} onOpenOAuth={() => void openOAuth()} onConnect={() => void connectAccount()} onToggleLive={toggleLive} onResolve={resolveQueue} replySettings={replySettings} replyQueue={replyQueue} replyToId={replyToId} replyText={replyText} replyBusy={replyBusy} onReplyToId={setReplyToId} onReplyText={setReplyText} onSubmitReply={(event) => void submitReply(event)} onToggleReplyLive={toggleReplyLive} onToggleReplyPaused={toggleReplyPaused} onResolveReply={resolveReply} />}
      <footer className="page-footer"><span>Semua waktu disimpan sebagai UTC.</span><span>Waktu yang ditampilkan dan diinput memakai Asia/Jakarta (WIB, UTC+7).</span></footer>
    </div></main>
  </div>;
}

function DashboardView({ themes, drafts, reviews, schedules, history, integrations, formatMix, demoActions, demoBusy, onRunDemo, onNavigate }: { themes: Theme[]; drafts: Draft[]; reviews: Draft[]; schedules: ScheduleEntry[]; history: HistoryItem[]; integrations: IntegrationStatus | null; formatMix?: EditorialSettings['formatMix']; demoActions: DemoAction[]; demoBusy: boolean; onRunDemo: () => void; onNavigate: (view: View) => void }) {
  const latest = [...history].sort((a, b) => b.executedAt.localeCompare(a.executedAt)).slice(0, 4);
  return <><div className="welcome-row"><div><p className="eyebrow">RUANG KERJA EDITORIAL</p><h1>Selamat datang di studio.</h1><p className="muted">Satu tempat untuk merawat ide, suara, dan jadwal konten.</p></div><Status tone="sim">● Simulasi aktif</Status></div>
    <section className="hero-card"><div className="hero-copy"><span className="hero-kicker">THREADS INDONESIA · EDITORIAL</span><h2>Hal kecil di umur 20-an<br /><em>yang ternyata banyak dialami.</em></h2><p>Observasi sehari-hari, obrolan yang terasa dekat, dan tren yang tetap nyambung dengan kehidupan audiens.</p><div className="hero-actions"><button className="button light" onClick={() => onNavigate('drafts')}>Buka draft <span>→</span></button><span className="hero-safe">Tidak ada post live</span></div></div><div className="hero-art" aria-hidden="true"><div className="sun-shape" /><div className="orbit orbit-one" /><div className="orbit orbit-two" /><span className="art-spark spark-one">✳</span><span className="art-spark spark-two">✦</span><div className="post-note"><span>IDE HARI INI</span><b>“Niat cek jam,<br />malah scroll lagi.”</b><small>kebiasaan digital</small></div></div></section>
    <div className="metric-grid"><Metric label="Tema aktif" value={themes.filter((theme) => theme.active).length} caption="pilar editorial" icon="✳" /><Metric label="Draft tersimpan" value={drafts.filter((draft) => draft.status !== 'CANCELLED').length} caption="siap dirawat" icon="▤" /><Metric label="Menunggu review" value={reviews.length} caption="tren perlu ditinjau" icon="◉" accent={reviews.length > 0} /><Metric label="Jadwal aktif" value={schedules.length} caption="eksekusi simulasi" icon="▦" /></div>
    <div className="dashboard-grid"><Panel title="Porsi format" description="Target mingguan lintas semua tema." actions={<button className="text-button" onClick={() => onNavigate('editorial')}>Atur porsi →</button>}><FormatBars formatMix={formatMix} /></Panel><Panel title="Koneksi layanan" description="Status yang terverifikasi saat ini."><div className="integration-summary">{integrations?.integrations.map((item) => <div className="integration-row" key={item.id}><span className="integration-icon">{item.id === 'gemini' ? '✦' : '◎'}</span><span><strong>{item.name}</strong><small>{item.connected ? 'Terhubung' : 'Belum terhubung'}</small></span><Status tone="warn">Belum terhubung</Status></div>)}</div><button className="text-button full-left" onClick={() => onNavigate('integrations')}>Lihat detail integrasi →</button></Panel></div>
    <Panel title="Simulasi lokal" description="Mempertahankan alur demo Phase 0 tanpa memanggil layanan eksternal." actions={<button className="button secondary" onClick={onRunDemo} disabled={demoBusy}>{demoBusy ? 'Menjalankan…' : 'Jalankan simulasi'}</button>}><p className="inline-note"><span className="pulse-dot" /> Aksi akan masuk antrean worker lokal. Tidak membuat draft, jadwal, atau publikasi nyata.</p>{demoActions.length === 0 ? <Empty>Belum ada simulasi demo.</Empty> : <div className="demo-list">{demoActions.slice(0, 3).map((action) => <div className="demo-row" key={action.id}><code>{action.id.slice(0, 8)}…</code><Status tone={action.status === 'FAILED' ? 'bad' : action.status === 'COMPLETED' ? 'good' : 'sim'}>{demoLabels[action.status]}</Status><span>{formatDate(action.createdAt)}</span><small>{action.result?.message ?? action.error ?? 'Menunggu worker…'}</small></div>)}</div>}</Panel>
    <Panel title="Eksekusi terbaru" description="Hasil dari adapter simulasi lokal." actions={<button className="text-button" onClick={() => onNavigate('history')}>Semua riwayat →</button>}>{latest.length === 0 ? <Empty>Belum ada eksekusi jadwal. Buat draft lalu atur jadwal simulasi.</Empty> : <div className="compact-history">{latest.map((item) => <div key={item.id} className="compact-history-row"><div><strong>{item.themeName}</strong><p>{item.draftText}</p></div><div><Status tone={item.status === 'SIMULATED_OK' ? 'good' : item.status === 'FAILED' ? 'bad' : 'neutral'}>{executionLabels[item.status]}</Status><small>{formatDate(item.executedAt)}</small></div></div>)}</div>}</Panel>
  </>;
}
function Metric({ label, value, caption, icon, accent = false }: { label: string; value: number; caption: string; icon: string; accent?: boolean }) { return <div className={`metric-card ${accent ? 'attention' : ''}`}><span className="metric-icon">{icon}</span><div><strong>{value}</strong><span>{label}</span><small>{caption}</small></div></div>; }
function FormatBars({ formatMix }: { formatMix?: EditorialSettings['formatMix'] }) { const mix = formatMix ?? { OBSERVASI_PENDEK: 70, BAHASAN_LEBIH_DALAM: 20, TREN_RELEVAN: 10 }; return <div className="format-bars"><div className="format-total"><strong>{mix.OBSERVASI_PENDEK} / {mix.BAHASAN_LEBIH_DALAM} / {mix.TREN_RELEVAN}</strong><span>format mix</span></div><div className="segmented-bar"><span className="seg short" style={{ width: `${mix.OBSERVASI_PENDEK}%` }} /><span className="seg deep" style={{ width: `${mix.BAHASAN_LEBIH_DALAM}%` }} /><span className="seg trend" style={{ width: `${mix.TREN_RELEVAN}%` }} /></div><div className="bar-legend"><span><i className="dot short" />Observasi pendek <b>{mix.OBSERVASI_PENDEK}%</b></span><span><i className="dot deep" />Bahasan lebih dalam <b>{mix.BAHASAN_LEBIH_DALAM}%</b></span><span><i className="dot trend" />Tren relevan <b>{mix.TREN_RELEVAN}%</b></span></div></div>; }

function EditorialView(props: {
  themes: Theme[]; weightsDraft: Record<string, string>; weightTotal: number; themeForm: ThemeForm; editingThemeId: string | null; settings: EditorialSettings | null; voices: VoiceExample[]; personalSources: PersonalSource[]; topics: ReviewTopic[]; saving: boolean; voiceText: string; personalNote: string; topicText: string;
  onThemeForm: (value: ThemeForm) => void; onSaveTheme: (event: FormEvent<HTMLFormElement>) => void; onEditTheme: (theme: Theme) => void; onCancelTheme: () => void; onWeightChange: (id: string, value: string) => void; onSaveWeights: () => void; onSettingsChange: (value: EditorialSettings | null) => void; onSaveSettings: () => void;
  onVoiceText: (value: string) => void; onAddVoice: (event: FormEvent<HTMLFormElement>) => void; onDeleteVoice: (id: string) => void; onPersonalNote: (value: string) => void; onAddPersonal: (event: FormEvent<HTMLFormElement>) => void; onDeletePersonal: (id: string) => void; onTopicText: (value: string) => void; onAddTopic: (event: FormEvent<HTMLFormElement>) => void; onTopicStatus: (topic: ReviewTopic) => void;
}) {
  const { themes, weightsDraft, weightTotal, themeForm, editingThemeId, settings, voices, personalSources, topics, saving } = props;
  return <><PageIntro eyebrow="PENGATURAN EDITORIAL" title="Tema & Gaya" description="Atur pilar cerita, porsi format, dan bahan yang membentuk suara akun." />
    <Panel title="Pilar editorial" description="Preset awal: tiga tema utama dan satu tema selingan. Bobot seluruh tema harus berjumlah 100%." actions={<span className={`total-chip ${weightTotal === 100 ? 'valid' : 'invalid'}`}>Total {weightTotal}%</span>}>{themes.length === 0 ? <Empty>Belum ada tema editorial.</Empty> : <div className="theme-list">{themes.map((theme) => <article className={`theme-card ${theme.active ? '' : 'inactive'}`} key={theme.id}><div className="theme-identity"><span className="theme-symbol">{theme.role === 'UTAMA' ? '✳' : '✦'}</span><div><h3>{theme.name}</h3><div className="tag-row"><span className="tag">{theme.role === 'UTAMA' ? 'Tema utama' : 'Tema selingan'}</span>{!theme.active && <Status>Nonaktif</Status>}</div></div></div><div className="theme-examples">{theme.examples.map((example, index) => <p key={`${theme.id}-${index}`}>“{example}”</p>)}</div><div className="theme-controls"><Field label="Bobot tema"><div className="input-suffix"><input aria-label={`Bobot ${theme.name}`} type="number" min="0" max="100" step="1" value={weightsDraft[theme.id] ?? '0'} onChange={(event) => props.onWeightChange(theme.id, event.target.value)} /><span>%</span></div></Field><button className="button ghost" onClick={() => props.onEditTheme(theme)}>Edit tema</button></div></article>)}</div>}<div className="panel-actions"><span className="muted">Edit bobot beberapa tema sekaligus, lalu simpan total 100%.</span><button className="button primary" onClick={props.onSaveWeights} disabled={saving || weightTotal !== 100}>Simpan bobot</button></div></Panel>
    <Panel title={editingThemeId ? 'Edit tema' : 'Tambah tema'} description="Simpan satu contoh tulisan per baris." className="editor-panel"><form id="theme-editor" className="form-grid" onSubmit={props.onSaveTheme}><Field label="Nama tema"><input value={themeForm.name} onChange={(event) => props.onThemeForm({ ...themeForm, name: event.target.value })} placeholder="Contoh: Rutinitas anak kos" required /></Field><Field label="Peran tema"><select value={themeForm.role} onChange={(event) => props.onThemeForm({ ...themeForm, role: event.target.value as ThemeRole })}><option value="UTAMA">Utama</option><option value="SELINGAN">Selingan</option></select></Field><Field label="Contoh tulisan" hint="Satu contoh per baris."><textarea rows={3} value={themeForm.examples} onChange={(event) => props.onThemeForm({ ...themeForm, examples: event.target.value })} required /></Field><label className="check-field"><input type="checkbox" checked={themeForm.active} onChange={(event) => props.onThemeForm({ ...themeForm, active: event.target.checked })} />Tema aktif</label><div className="form-actions"><button className="button primary" disabled={saving}>{editingThemeId ? 'Simpan perubahan' : 'Buat tema'}</button>{editingThemeId && <button type="button" className="button ghost" onClick={props.onCancelTheme}>Batal edit</button>}</div></form></Panel>
    {settings && <Panel title="Campuran format" description="Target mingguan format lintas tema. Jumlah semua porsi harus tepat 100%." actions={<span className={`total-chip ${Object.values(settings.formatMix).reduce((sum, value) => sum + value, 0) === 100 ? 'valid' : 'invalid'}`}>Total {Object.values(settings.formatMix).reduce((sum, value) => sum + value, 0)}%</span>}><div className="mix-grid">{(Object.keys(formatLabels) as ContentFormat[]).map((format) => <Field key={format} label={formatLabels[format]}><div className="input-suffix"><input type="number" min="0" max="100" step="1" value={settings.formatMix[format]} onChange={(event) => props.onSettingsChange({ ...settings, formatMix: { ...settings.formatMix, [format]: Number(event.target.value) } })} /><span>%</span></div></Field>)}</div><div className="mix-preview"><span className="mix-observation" style={{ width: `${settings.formatMix.OBSERVASI_PENDEK}%` }} /><span className="mix-deep" style={{ width: `${settings.formatMix.BAHASAN_LEBIH_DALAM}%` }} /><span className="mix-trend" style={{ width: `${settings.formatMix.TREN_RELEVAN}%` }} /></div><div className="panel-actions"><span className="muted">Default Phase 1: 70% observasi · 20% bahasan · 10% tren.</span><button className="button primary" onClick={props.onSaveSettings} disabled={saving || Object.values(settings.formatMix).reduce((sum, value) => sum + value, 0) !== 100}>Simpan campuran</button></div></Panel>}
    {settings && <Panel title="Batas & jeda publikasi" description="Pagar kerja harian untuk antrean. Semua eksekusi tetap simulasi lokal."><div className="settings-row"><Field label="Batas post per hari" hint="Dihitung per hari kalender Asia/Jakarta."><div className="input-suffix limit-input"><input type="number" min="1" max="20" value={settings.dailyPostLimit} onChange={(event) => props.onSettingsChange({ ...settings, dailyPostLimit: Number(event.target.value) })} /><span>post</span></div></Field><label className={`pause-toggle ${settings.paused ? 'paused' : ''}`}><input type="checkbox" checked={settings.paused} onChange={(event) => props.onSettingsChange({ ...settings, paused: event.target.checked })} /><span className="toggle-track"><i /></span><span><strong>{settings.paused ? 'Jeda aktif' : 'Publikasi dijeda?'}</strong><small>{settings.paused ? 'Worker akan melewati jadwal saat jeda aktif.' : 'Aktifkan untuk menahan eksekusi jadwal.'}</small></span></label><button className="button primary settings-save" onClick={props.onSaveSettings} disabled={saving}>Simpan pengaturan</button></div></Panel>}
    <div className="two-column"><Panel title="Contoh suara akun" description="Frasa dan tulisan untuk menjaga pilihan kata ganti serta gaya." className="fill-panel"><form className="inline-form" onSubmit={props.onAddVoice}><textarea rows={2} value={props.voiceText} onChange={(event) => props.onVoiceText(event.target.value)} placeholder="Tulis contoh suara akun…" required /><button className="button secondary" disabled={saving}>Tambah contoh</button></form>{voices.length === 0 ? <Empty>Belum ada contoh suara.</Empty> : <div className="note-list">{voices.map((item) => <div className="note-card" key={item.id}><p>“{item.text}”</p><button className="icon-button small" aria-label="Hapus contoh suara" onClick={() => props.onDeleteVoice(item.id)}>×</button></div>)}</div>}</Panel>
      <Panel title="Catatan pengalaman pemilik" description="Sumber pengalaman pribadi hanya dari catatan yang ditambahkan pemilik." className="fill-panel"><form className="inline-form" onSubmit={props.onAddPersonal}><textarea rows={2} value={props.personalNote} onChange={(event) => props.onPersonalNote(event.target.value)} placeholder="Catatan pengalaman pribadi…" required /><button className="button secondary" disabled={saving}>Simpan catatan</button></form>{personalSources.length === 0 ? <Empty>Belum ada catatan pengalaman.</Empty> : <div className="note-list">{personalSources.map((item) => <div className="note-card" key={item.id}><p>{item.note}</p><button className="icon-button small" aria-label="Hapus catatan pemilik" onClick={() => props.onDeletePersonal(item.id)}>×</button></div>)}</div>}</Panel></div>
    <Panel title="Topik yang perlu ditinjau" description="Catat topik editorial yang perlu dipantau atau sudah ditangani."><form className="topic-form" onSubmit={props.onAddTopic}><input value={props.topicText} onChange={(event) => props.onTopicText(event.target.value)} placeholder="Tambah topik untuk review…" required /><button className="button secondary" disabled={saving}>Tambah topik</button></form>{topics.length === 0 ? <Empty>Belum ada topik review.</Empty> : <div className="topic-list">{topics.map((topic) => <div className="topic-row" key={topic.id}><span className="topic-dot" /><strong>{topic.topic}</strong><Status tone={topic.status === 'OPEN' ? 'warn' : 'good'}>{topic.status === 'OPEN' ? 'Terbuka' : 'Selesai'}</Status><button className="text-button" onClick={() => props.onTopicStatus(topic)}>{topic.status === 'OPEN' ? 'Tandai selesai' : 'Buka kembali'}</button></div>)}</div>}</Panel>
  </>;
}
function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="page-intro"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="muted">{description}</p></div>{action}</div>; }
function TrendsView({ settings, items, candidates, run, busy, saving, onRefresh, onSettings, onSaveSettings, onDismiss }: {
  settings: TrendSettings | null; items: TrendItem[]; candidates: TrendCandidate[]; run: TrendRun | null;
  busy: boolean; saving: boolean;
  onRefresh: () => void; onSettings: (value: TrendSettings) => void; onSaveSettings: () => void; onDismiss: (id: string) => void;
}) {
  const [sourceId, setSourceId] = useState(''); const [sourceName, setSourceName] = useState(''); const [sourceUrl, setSourceUrl] = useState('');
  const sources = settings?.sources ?? [];
  const addSource = () => {
    const id = sourceId.trim(); const name = sourceName.trim(); const url = sourceUrl.trim();
    if (!id || !name || !/^https:\/\/.+/.test(url)) return;
    if (sources.some((source) => source.id === id)) return;
    onSettings({ ...settings!, sources: [...sources, { id, name, url }] });
    setSourceId(''); setSourceName(''); setSourceUrl('');
  };
  return <>
    <PageIntro eyebrow="DISCOVERY TREN" title="Tren & sumber" description="Ambil berita terkini dari sumber RSS, skor relevansinya dihitung, lalu kandidat terbaik masuk review. Tidak ada kiriman otomatis." action={<button className="button primary" onClick={onRefresh} disabled={busy}>{busy ? 'Menjalankan…' : 'Jelajahi tren sekarang'}</button>} />
    {run && <div className="alert success" role="status"><span>Run {run.id.slice(0, 8)}… · {run.status}{run.result ? ` · ${JSON.stringify(run.result)}` : ''}</span></div>}
    <Panel title="Sumber & ambang" description="Discovery memakai RSS/Atom publik. Kandidat dibuat bila skor ≥ ambang, maksimal batas harian.">
      {!settings ? <Empty>Memuat pengaturan…</Empty> : <>
        <div className="settings-row">
          <Field label="Ambang skor (0–100)"><div className="input-suffix"><input type="number" min={0} max={100} value={settings.threshold} onChange={(event) => onSettings({ ...settings, threshold: Number(event.target.value) })} /><span>poin</span></div></Field>
          <Field label="Batas kandidat per hari"><div className="input-suffix"><input type="number" min={1} max={100} value={settings.dailyLimit} onChange={(event) => onSettings({ ...settings, dailyLimit: Number(event.target.value) })} /><span>kandidat</span></div></Field>
          <label className="check-field"><input type="checkbox" checked={settings.enabled} onChange={(event) => onSettings({ ...settings, enabled: event.target.checked })} />Discovery aktif</label>
          <label className="check-field"><input type="checkbox" checked={settings.paused} onChange={(event) => onSettings({ ...settings, paused: event.target.checked })} />Jeda discovery</label>
        </div>
        <div className="panel-actions"><button className="button primary" onClick={onSaveSettings} disabled={saving}>Simpan pengaturan</button></div>
        <h3>Sumber</h3>
        <div className="topic-list">{sources.map((source) => <div className="topic-row" key={source.id}><span className="topic-dot" /><strong>{source.name}</strong><small>{source.url}</small><button className="text-button" onClick={() => onSettings({ ...settings, sources: sources.filter((item) => item.id !== source.id) })}>Hapus</button></div>)}</div>
        <div className="inline-form"><input value={sourceId} onChange={(event) => setSourceId(event.target.value)} placeholder="id (mis. detik)" /><input value={sourceName} onChange={(event) => setSourceName(event.target.value)} placeholder="Nama sumber" /><input value={sourceUrl} onChange={(event) => setSourceUrl(event.target.value)} placeholder="https://…/rss" /><button className="button secondary" onClick={addSource} disabled={saving}>Tambah sumber</button></div>
      </>}
    </Panel>
    <Panel title={`Kandidat tren (${candidates.length})`} description="Kandidat di atas ambang otomatis menjadi draft TREN_RELEVAN dan masuk antrean review.">{candidates.length === 0 ? <Empty>Belum ada kandidat. Jalankan discovery untuk mengisi.</Empty> : <div className="note-list">{candidates.map((candidate) => <article className="note-card" key={candidate.id}><div><strong>{candidate.title}</strong><p>{candidate.sourceName} · skor {candidate.score}/100 (ambang {candidate.threshold}) · {candidate.status === 'CONVERTED' ? 'Draft dibuat' : candidate.status === 'DISMISSED' ? 'Dibuang' : 'Menunggu'}</p><p className="muted">{candidate.reasons.map((reason) => `${reason.label} ${reason.points}`).join(' · ')}</p></div><div className="draft-actions"><a className="text-button" href={candidate.url} target="_blank" rel="noreferrer">Buka sumber</a>{candidate.status === 'PENDING' && <button className="text-button" onClick={() => onDismiss(candidate.id)}>Buang</button>}</div></article>)}</div>}</Panel>
    <Panel title={`Item terbaru (${items.length})`} description="Item di bawah ambang tetap disimpan sebagai bahan pantauan.">{items.length === 0 ? <Empty>Belum ada item.</Empty> : <div className="note-list">{items.slice(0, 20).map((item) => <article className="note-card" key={item.id}><div><strong>{item.title}</strong><p>{item.sourceName} · {formatDate(item.publishedAt)}</p></div><a className="text-button" href={item.url} target="_blank" rel="noreferrer">Buka</a></article>)}</div>}</Panel>
  </>;
}
function DraftEditor({ themes, personalSources, form, editing, saving, onForm, onSubmit, onCancelEdit }: { themes: Theme[]; personalSources: PersonalSource[]; form: DraftForm; editing: Draft | null; saving: boolean; onForm: (value: DraftForm) => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onCancelEdit: () => void }) {
  const isTrend = form.format === 'TREN_RELEVAN';
  return <Panel title={editing ? 'Edit draft' : 'Buat draft'} description="Draft tren wajib punya URL sumber, waktu sumber, dan alasan relevansi sebelum masuk review." className="editor-panel"><form id="draft-editor" className="form-grid" onSubmit={onSubmit}><Field label="Tema"><select value={form.themeId} onChange={(event) => onForm({ ...form, themeId: event.target.value })} required><option value="">Pilih tema</option>{themes.filter((theme) => theme.active).map((theme) => <option key={theme.id} value={theme.id}>{theme.name}</option>)}</select></Field><Field label="Format"><select value={form.format} onChange={(event) => onForm({ ...form, format: event.target.value as ContentFormat })}><option value="OBSERVASI_PENDEK">Observasi pendek</option><option value="BAHASAN_LEBIH_DALAM">Bahasan lebih dalam</option><option value="TREN_RELEVAN">Tren relevan · perlu review</option></select></Field><Field label="Teks draft"><textarea rows={4} value={form.text} onChange={(event) => onForm({ ...form, text: event.target.value })} placeholder="Tulis observasi yang terasa dekat dengan keseharian audiens…" required /></Field><Field label="Sumber pengalaman pemilik" hint="Opsional. Jika dipilih, sumber hanya berasal dari catatan pemilik tersimpan."><select value={form.personalSourceId} onChange={(event) => onForm({ ...form, personalSourceId: event.target.value })}><option value="">Tidak memakai catatan pribadi</option>{personalSources.map((source) => <option key={source.id} value={source.id}>{source.note.slice(0, 90)}</option>)}</select></Field>{isTrend && <div className="trend-fields"><div className="trend-warning"><strong>Draft tren masuk antrean review.</strong><span>Lengkapi bukti sumber dan kaitan yang jelas dengan audiens.</span></div><Field label="URL sumber"><input type="url" value={form.sourceUrl} onChange={(event) => onForm({ ...form, sourceUrl: event.target.value })} placeholder="https://…" required /></Field><Field label="Waktu sumber · Asia/Jakarta"><input type="datetime-local" value={form.sourceTime} onChange={(event) => onForm({ ...form, sourceTime: event.target.value })} required /><small>WIB (UTC+7); dikirim dan disimpan sebagai UTC.</small></Field><Field label="Kenapa relevan dengan audiens?"><textarea rows={2} value={form.relevanceNote} onChange={(event) => onForm({ ...form, relevanceNote: event.target.value })} placeholder="Jelaskan kaitannya dengan detail keseharian usia 20-an…" required /></Field></div>}<div className="form-actions"><button className="button primary" disabled={saving || !themes.length}>{editing ? 'Simpan draft' : isTrend ? 'Kirim ke review' : 'Simpan draft'}</button>{editing && <button type="button" className="button ghost" onClick={onCancelEdit}>Batal edit</button>}</div></form></Panel>;
}
function DraftsView({ themes, drafts, personalSources, form, editing, saving, onForm, onSubmit, onEdit, onCancelEdit, onLock }: { themes: Theme[]; drafts: Draft[]; personalSources: PersonalSource[]; form: DraftForm; editing: Draft | null; saving: boolean; onForm: (value: DraftForm) => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onEdit: (draft: Draft) => void; onCancelEdit: () => void; onLock: (draft: Draft) => void }) { return <><PageIntro eyebrow="RUANG MENULIS" title="Draft konten" description="Simpan dan rapikan draft manual sebelum disetujui atau dimasukkan ke jadwal simulasi." action={<Status tone="sim">Publikasi tetap simulasi</Status>} /><DraftEditor themes={themes} personalSources={personalSources} form={form} editing={editing} saving={saving} onForm={onForm} onSubmit={onSubmit} onCancelEdit={onCancelEdit} /><Panel title="Semua draft" description={`${drafts.length} draft tersimpan. Draft terkunci hanya bisa diedit setelah dibuka kembali.`}>{drafts.length === 0 ? <Empty>Belum ada draft. Mulai dari editor di atas.</Empty> : <div className="draft-list">{drafts.map((draft) => <DraftCard key={draft.id} draft={draft} onEdit={onEdit} onLock={onLock} />)}</div>}</Panel></>; }
function DraftCard({ draft, onEdit, onLock, reviewActions }: { draft: Draft; onEdit: (draft: Draft) => void; onLock: (draft: Draft) => void; reviewActions?: ReactNode }) { return <article className="draft-card"><div className="draft-card-top"><div><div className="tag-row"><span className="tag">{draft.themeName}</span><span className="tag subtle-tag">{formatLabels[draft.format]}</span></div><p className="draft-copy">{draft.text}</p></div><Status tone={draft.status === 'IN_REVIEW' ? 'warn' : draft.status === 'APPROVED' ? 'good' : draft.status === 'CANCELLED' ? 'bad' : 'neutral'}>{draftLabels[draft.status]}</Status></div><div className="draft-meta"><span>Versi {draft.version}</span><span>{draft.locked ? 'Terkunci' : 'Bisa diedit'}</span><span>Diperbarui {formatDate(draft.updatedAt)}</span>{draft.format === 'TREN_RELEVAN' && draft.sourceTime && <span>Sumber · {formatDate(draft.sourceTime)}</span>}</div>{draft.format === 'TREN_RELEVAN' && <div className="source-box"><span><strong>Sumber</strong> {draft.sourceUrl ? <a href={draft.sourceUrl} target="_blank" rel="noreferrer">{draft.sourceUrl}</a> : 'Belum tersedia'}</span><span><strong>Relevansi</strong> {draft.relevanceNote || 'Belum dijelaskan'}</span></div>}{draft.reviewNote && <p className="review-note">Catatan review: {draft.reviewNote}</p>}<div className="draft-actions">{draft.status !== 'CANCELLED' && <><button className="button ghost" onClick={() => onEdit(draft)} disabled={draft.locked}>Edit</button><button className="button ghost" onClick={() => onLock(draft)}>{draft.locked ? 'Buka kunci' : 'Kunci draft'}</button></>}{reviewActions}</div></article>; }
function ReviewView({ drafts, notes, saving, onNote, onDecision, onEdit, onLock }: { drafts: Draft[]; notes: Record<string, string>; saving: boolean; onNote: (id: string, value: string) => void; onDecision: (draft: Draft, decision: 'APPROVE' | 'REJECT') => void; onEdit: (draft: Draft) => void; onLock: (draft: Draft) => void }) { return <><PageIntro eyebrow="GERBANG EDITORIAL" title="Review tren" description="Periksa sumber, waktu, dan kaitan tren dengan keseharian audiens sebelum menyetujui." action={<Status tone={drafts.length ? 'warn' : 'good'}>{drafts.length} menunggu</Status>} /><div className="review-callout"><span className="callout-icon">◉</span><div><strong>Tren tidak otomatis dipakai.</strong><p>Setiap draft tren harus punya sumber yang dapat dibuka, waktu sumber, serta alasan relevansi. Jika tidak cocok, kembalikan sebagai draft biasa.</p></div></div>{drafts.length === 0 ? <Panel title="Antrean review"><Empty>Antrean review kosong. Draft tren yang baru dibuat akan muncul di sini.</Empty></Panel> : <div className="review-list">{drafts.map((draft) => <div className="review-card" key={draft.id}><DraftCard draft={draft} onEdit={onEdit} onLock={onLock} /><Field label="Catatan reviewer" hint="Opsional; akan tersimpan bersama keputusan."><input value={notes[draft.id] ?? ''} onChange={(event) => onNote(draft.id, event.target.value)} placeholder="Sumber jelas, relate, atau alasan dikembalikan…" /></Field><div className="review-actions"><button className="button ghost" onClick={() => onEdit(draft)} disabled={draft.locked}>Edit sumber / teks</button><button className="button danger-outline" disabled={saving} onClick={() => onDecision(draft, 'REJECT')}>Kembalikan</button><button className="button primary" disabled={saving} onClick={() => onDecision(draft, 'APPROVE')}>Setujui tren</button></div></div>)}</div>}</>; }
function ScheduleView({ schedules, eligibleDrafts, draftId, scheduledAt, saving, onDraftId, onScheduledAt, onSubmit, onReschedule, onCancel }: { schedules: ScheduleEntry[]; eligibleDrafts: Draft[]; draftId: string; scheduledAt: string; saving: boolean; onDraftId: (value: string) => void; onScheduledAt: (value: string) => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onReschedule: (entry: ScheduleEntry, value: string) => void; onCancel: (entry: ScheduleEntry) => void }) {
  const [rescheduleId, setRescheduleId] = useState<string | null>(null); const [rescheduleValue, setRescheduleValue] = useState(''); const sorted = [...schedules].sort((a, b) => a.scheduledAt.localeCompare(b.scheduledAt));
  const grouped = sorted.reduce<Record<string, ScheduleEntry[]>>((result, entry) => { const day = new Date(new Date(entry.scheduledAt).getTime() + 7 * 3600_000).toISOString().slice(0, 10); (result[day] ??= []).push(entry); return result; }, {});
  return <><PageIntro eyebrow="KALENDER DAFTAR" title="Jadwal publikasi" description="Atur waktu lokal untuk simulasi worker. Tidak ada post yang dikirim ke Threads." action={<Status tone="sim">Simulasi saja</Status>} /><Panel title="Buat jadwal simulasi" description="Pilih draft yang tidak lagi menunggu review dan waktu Asia/Jakarta."><form className="schedule-form" onSubmit={onSubmit}><Field label="Draft"><select value={draftId} onChange={(event) => onDraftId(event.target.value)} required><option value="">Pilih draft</option>{eligibleDrafts.map((draft) => <option key={draft.id} value={draft.id}>{draft.themeName} · {formatLabels[draft.format]} · {draft.text.slice(0, 50)}</option>)}</select></Field><Field label="Tanggal & waktu · Asia/Jakarta"><input type="datetime-local" value={scheduledAt} onChange={(event) => onScheduledAt(event.target.value)} required /><small>WIB (UTC+7); disimpan dalam UTC. Batas harian memakai tanggal WIB.</small></Field><button className="button primary" disabled={saving || eligibleDrafts.length === 0}>Tambahkan jadwal</button></form>{eligibleDrafts.length === 0 && <p className="inline-warning">Belum ada draft yang siap dijadwalkan. Draft tren harus disetujui lebih dulu.</p>}</Panel><Panel title="Daftar jadwal" description={`${schedules.length} jadwal tercatat; waktu di bawah mengikuti kalender Asia/Jakarta.`}>{sorted.length === 0 ? <Empty>Belum ada jadwal. Simpan draft untuk memulai.</Empty> : <div className="calendar-list">{Object.entries(grouped).map(([day, entries]) => <div className="calendar-day" key={day}><div className="calendar-date"><span>{new Intl.DateTimeFormat('id-ID', { weekday: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(`${day}T12:00:00+07:00`))}</span><strong>{dateOnly.format(new Date(`${day}T12:00:00+07:00`))}</strong></div><div className="calendar-items">{entries.map((entry) => <article className={`schedule-card ${entry.status.toLowerCase()}`} key={entry.id}><div className="schedule-time"><strong>{dateTime.format(new Date(entry.scheduledAt)).split(' pukul ')[1] ?? dateTime.format(new Date(entry.scheduledAt)).slice(-5)}</strong><span>WIB</span></div><div className="schedule-body"><div className="tag-row"><span className="tag">{entry.themeName}</span><Status tone={entry.status === 'SCHEDULED' ? 'sim' : entry.status === 'COMPLETED' ? 'good' : 'neutral'}>{entry.status === 'SCHEDULED' ? 'Terjadwal' : entry.status === 'COMPLETED' ? 'Selesai simulasi' : 'Dibatalkan'}</Status></div><p>{entry.draftText}</p><small>{formatLabels[entry.format]} · versi jadwal {entry.version}</small></div><div className="schedule-actions">{entry.status === 'SCHEDULED' && <><button className="text-button" onClick={() => { setRescheduleId(entry.id); setRescheduleValue(jakartaInputValue(entry.scheduledAt)); }}>Jadwalkan ulang</button><button className="text-button danger-text" onClick={() => onCancel(entry)}>Batalkan</button></>}</div>{rescheduleId === entry.id && <div className="reschedule-box"><Field label="Waktu baru · Asia/Jakarta"><input type="datetime-local" value={rescheduleValue} onChange={(event) => setRescheduleValue(event.target.value)} /></Field><button className="button primary compact" disabled={saving || !rescheduleValue} onClick={() => { onReschedule(entry, rescheduleValue); setRescheduleId(null); }}>Simpan waktu</button><button className="button ghost compact" onClick={() => setRescheduleId(null)}>Batal</button></div>}</article>)}</div></div>)}</div>}</Panel></>;
}
export function HistoryView({ items, themes, filters, loading, onFilterChange, onSubmit, onReset }: { items: HistoryItem[]; themes: Theme[]; filters: HistoryFilters; loading: boolean; onFilterChange: (value: HistoryFilters) => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onReset: () => void }) { return <><PageIntro eyebrow="CATATAN EKSEKUSI" title="Riwayat" description="Filter hasil simulasi berdasarkan status, tema, format, dan rentang tanggal Jakarta." action={<Status tone="sim">Data simulasi</Status>} /><Panel title="Filter riwayat" description="Filter memakai snapshot versi jadwal, bukan draft saat ini. Nama pilihan tema mengikuti nama kini; hasil menyimpan nama historis. Tanggal memakai kalender Asia/Jakarta."><form className="history-filters" onSubmit={onSubmit}><Field label="Status"><select value={filters.status} onChange={(event) => onFilterChange({ ...filters, status: event.target.value })}><option value="">Semua status</option>{(Object.keys(executionLabels) as ExecutionStatus[]).map((status) => <option key={status} value={status}>{executionLabels[status]}</option>)}</select></Field><Field label="Tema"><select value={filters.themeId} onChange={(event) => onFilterChange({ ...filters, themeId: event.target.value })}><option value="">Semua tema</option>{themes.map((theme) => <option key={theme.id} value={theme.id}>{theme.name}</option>)}</select></Field><Field label="Format"><select value={filters.format} onChange={(event) => onFilterChange({ ...filters, format: event.target.value })}><option value="">Semua format</option>{(Object.keys(formatLabels) as ContentFormat[]).map((format) => <option key={format} value={format}>{formatLabels[format]}</option>)}</select></Field><Field label="Dari · tanggal Jakarta"><input type="date" value={filters.from} onChange={(event) => onFilterChange({ ...filters, from: event.target.value })} /></Field><Field label="Sampai · tanggal Jakarta"><input type="date" value={filters.to} onChange={(event) => onFilterChange({ ...filters, to: event.target.value })} /></Field><div className="filter-actions"><button className="button primary" disabled={loading}>{loading ? 'Memuat…' : 'Terapkan filter'}</button><button type="button" className="button ghost" onClick={onReset}>Reset</button></div></form></Panel><Panel title="Hasil eksekusi" description={`${items.length} catatan ditampilkan; maksimal 100 hasil terbaru.`}>{items.length === 0 ? <Empty>Tidak ada hasil untuk filter ini.</Empty> : <div className="history-list">{items.map((item) => <article className="history-card" key={item.id}><div className="history-main"><div className="tag-row"><span className="tag">{item.themeName ?? 'Tema tidak diketahui'}</span><span className="tag subtle-tag">{item.format ? formatLabels[item.format] : 'Format tidak diketahui'}</span><Status tone={item.status === 'SIMULATED_OK' ? 'good' : item.status === 'FAILED' ? 'bad' : item.status === 'CANCELLED' ? 'neutral' : 'warn'}>{executionLabels[item.status]}</Status><Status tone="sim">SIMULASI</Status></div><small>{item.snapshotProvenance === 'CAPTURED' ? 'Snapshot eksekusi' : 'Metadata historis tidak lengkap · data lama'}</small><p>{item.draftText ?? 'Teks historis tidak tersedia'}</p>{item.error && <p className="history-error">{item.error}</p>}{typeof item.result?.message === 'string' && <p className="history-result">{item.result.message}</p>}</div><div className="history-times"><span><small>Jadwal</small><strong>{formatDate(item.scheduledAt)}</strong></span><span><small>Dicatat</small><strong>{formatDate(item.executedAt)}</strong></span><small>Versi {item.version}</small></div></article>)}</div>}</Panel></>; }
function IntegrationsView({ integrations }: { integrations: IntegrationStatus | null }) { return <><PageIntro eyebrow="KONEKSI EKSTERNAL" title="Integrasi" description="Status publikasi terpisah dari provider generasi. Lihat Konten Gemini di halaman Draft untuk konfigurasi dan pemakaian." action={<Status tone="sim">Mode simulasi</Status>} /><div className="integration-banner"><span className="integration-banner-icon">◎</span><div><strong>Publikasi live nonaktif</strong><p>Akun Meta belum terhubung. Generasi memakai provider yang ditampilkan di Konten Gemini; tidak mengaktifkan publikasi live.</p></div></div><div className="integration-cards">{integrations?.integrations.map((item) => <article className="integration-card" key={item.id}><div className="integration-card-head"><span className="integration-icon large">{item.id === 'gemini' ? '✦' : '◎'}</span><Status tone="warn">Belum terhubung</Status></div><p className="eyebrow">{item.id === 'gemini' ? 'KONTEN' : 'PUBLIKASI'}</p><h2>{item.name}</h2><p>{item.note}</p><div className="integration-card-foot"><span className="integration-status-dot" />{item.mode === 'SIMULASI' ? 'Adapter simulasi' : 'Belum dikonfigurasi'}<span className="integration-no-live">Tidak ada akses live</span></div></article>)}</div><Panel title="Batas cakupan publikasi" description="Pemisahan mode membantu mencegah hasil simulasi disalahartikan sebagai hasil akun nyata."><ul className="plain-list"><li><strong>Meta Threads:</strong> status koneksi dan antrean publish ada di halaman Publikasi.</li><li><strong>Gemini:</strong> provider generasi dapat dikonfigurasi di server; status dan penggunaan tertera di Konten Gemini. Simulasi bukan bukti uji API live.</li><li><strong>Jadwal:</strong> saat live mati, worker menyimpan hasil dengan penanda simulasi, bukan membuat post nyata.</li><li><strong>Rahasia:</strong> dashboard tidak meminta, menyimpan, atau menampilkan credential integrasi.</li></ul></Panel></>; }

type PublishViewProps = {
  connection: ConnectionStatus | null; publishQueue: PublishQueueItem[]; drafts: Draft[]; publishDraftId: string; publishBusy: boolean;
  onPublishDraftId: (value: string) => void; onSubmitPublish: (event: FormEvent<HTMLFormElement>) => void;
  onOpenOAuth: () => void; onConnect: () => void; onToggleLive: (live: boolean) => void;
  onResolve: (item: PublishQueueItem, resolution: 'PUBLISHED' | 'FAILED') => void;
  replySettings: ReplySettings | null; replyQueue: ReplyQueueItem[]; replyToId: string; replyText: string; replyBusy: boolean;
  onReplyToId: (value: string) => void; onReplyText: (value: string) => void; onSubmitReply: (event: FormEvent<HTMLFormElement>) => void;
  onToggleReplyLive: (live: boolean) => void; onToggleReplyPaused: () => void;
  onResolveReply: (item: ReplyQueueItem, resolution: 'REPLIED' | 'FAILED') => void;
};

const replyLabels: Record<string, string> = { QUEUED: 'Antre', CONTAINER_CREATED: 'Container dibuat', REPLIED: 'Terbalas', NEEDS_REVIEW: 'Perlu rekonsiliasi', FAILED: 'Gagal', DUPLICATE: 'Duplikat', REQUIRES_LIVE: 'Live balasan belum aktif' };

function ThreadsPublishView({ connection, publishQueue, drafts, publishDraftId, publishBusy, onPublishDraftId, onSubmitPublish, onOpenOAuth, onConnect, onToggleLive, onResolve, replySettings, replyQueue, replyToId, replyText, replyBusy, onReplyToId, onReplyText, onSubmitReply, onToggleReplyLive, onToggleReplyPaused, onResolveReply }: PublishViewProps) {
  const live = Boolean(connection?.livePosting);
  const eligible = drafts.filter((draft) => ['APPROVED', 'SCHEDULED', 'DRAFT'].includes(draft.status));
  return <><PageIntro eyebrow="PUBLIKASI THREADS" title="Posting manual & terjadwal" description="Posting live dimatikan secara default. Aktifkan hanya setelah akun uji siap; hasil tetap bisa direkonsiliasi." action={<Status tone={live ? 'good' : 'sim'}>{live ? 'Live aktif' : 'Live nonaktif'}</Status>} />
    <div className={`integration-banner ${live ? '' : 'muted'}`}><span className="integration-banner-icon">▶</span><div><strong>{live ? 'Publikasi live aktif' : 'Publikasi live nonaktif'}</strong><p>{live ? 'Jadwal dan posting manual masuk antrean Meta Threads. Timeout/restart tidak menghasilkan post ganda.' : 'Antrean tetap dicatat sebagai bukti, tapi tidak ada post nyata. Aktifkan live untuk benar-benar terbit.'}</p></div></div>
    <div className="two-column">
      <Panel title="Koneksi Meta Threads" description="Status token dan app. Rahasia tidak pernah ditampilkan."><div className="settings-row"><div><span className="muted">App ID</span><strong>{connection?.appId ? 'Terisi' : 'Belum diisi'}</strong></div><div><span className="muted">User ID</span><strong>{connection?.userId ?? 'Belum terhubung'}</strong></div><div><span className="muted">Token</span><strong>{connection?.accessTokenPresent ? `Ada · kedaluwarsa ${formatDate(connection.tokenExpiresAt)}` : 'Belum ada'}</strong></div><div><span className="muted">Scope</span><strong>{connection?.scopes ?? 'threads_basic, threads_content_publish'}</strong></div></div><div className="panel-actions"><button className="button secondary" onClick={onOpenOAuth}>Buka halaman OAuth Meta</button><button className="button secondary" onClick={onConnect}>Hubungkan akun</button><button className={`button ${live ? 'danger-outline' : 'primary'}`} onClick={() => onToggleLive(!live)}>{live ? 'Matikan live' : 'Aktifkan live'}</button></div><small>Token long-lived 60 hari; dashboard hanya menampilkan status, bukan nilai token.</small></Panel>
      <Panel title="Posting manual dari dashboard" description="Pilih draft yang sudah siap. Teks maksimal 500 karakter (batas Meta)."><form className="schedule-form" onSubmit={onSubmitPublish}><Field label="Draft"><select value={publishDraftId} onChange={(event) => onPublishDraftId(event.target.value)} required><option value="">Pilih draft</option>{eligible.map((draft) => <option key={draft.id} value={draft.id}>{draft.themeName} · {formatLabels[draft.format]} · {draft.text.slice(0, 50)}</option>)}</select></Field><button className="button primary" disabled={publishBusy || !publishDraftId}>{publishBusy ? 'Mengantrekan…' : live ? 'Kirim ke antrean Meta' : 'Catat antrean (live mati)'}</button></form>{!live && <p className="inline-warning">Live nonaktif: antrean dicatat dengan status REQUIRES_LIVE; tidak ada post nyata.</p>}</Panel>
    </div>
    <Panel title="Antrean & hasil publish" description="Status PUBLISHED hanya muncul dengan media ID dari Meta. NEEDS_REVIEW berarti hasil ambigu dan menunggu rekonsiliasi operator.">{publishQueue.length === 0 ? <Empty>Belum ada antrean publish. Posting manual atau jadwal live akan muncul di sini.</Empty> : <div className="note-list">{publishQueue.slice(0, 20).map((item) => <article className="note-card" key={item.id}><div><strong>{item.trigger === 'MANUAL' ? 'Manual' : 'Terjadwal'} · {publishLabels[item.status] ?? item.status}</strong><p>{item.mediaId ? `Media ID: ${item.mediaId}` : item.containerId ? `Container: ${item.containerId}` : 'Menunggu worker…'}</p>{item.publishedUrl && <p><a href={item.publishedUrl} target="_blank" rel="noreferrer">Buka di Threads</a></p>}{item.lastError && <p role="alert">{item.lastError}</p>}<small>Percobaan {item.attemptCount} · {formatDate(item.createdAt)}</small>{item.status === 'NEEDS_REVIEW' && <div className="panel-actions"><button className="button secondary" onClick={() => onResolve(item, 'PUBLISHED')}>Tandai terbit</button><button className="button danger-outline" onClick={() => onResolve(item, 'FAILED')}>Tandai gagal</button></div>}</div></article>)}</div>}</Panel>
    <Panel title="Balasan Threads (Fase 4B)" description="Balasan memakai scope threads_manage_replies. Live dan jeda balasan TERPISAH dari publikasi post; anti-duplikat per media + teks.">
      <div className="settings-row">
        <div><span className="muted">Live balasan</span><strong>{replySettings?.livePosting ? 'Aktif' : 'Nonaktif'}</strong></div>
        <div><span className="muted">Status</span><strong>{replySettings?.paused ? 'Dijeda' : 'Berjalan'}</strong></div>
        <div><span className="muted">Batas harian</span><strong>{replySettings?.dailyLimit ?? '—'} balasan</strong></div>
        <div><span className="muted">Kuota Meta</span><strong>{replySettings?.quotaUsage != null ? `${replySettings.quotaUsage}/${replySettings.quotaTotal ?? '?'} (24 jam)` : 'Belum diketahui'}</strong></div>
      </div>
      <form className="schedule-form" onSubmit={onSubmitReply}>
        <Field label="Media ID yang dibalas"><input value={replyToId} onChange={(event) => onReplyToId(event.target.value)} placeholder="contoh: 18033566909883283" required /></Field>
        <Field label="Teks balasan"><textarea rows={2} value={replyText} onChange={(event) => onReplyText(event.target.value)} maxLength={500} placeholder="Tulis balasan…" required /></Field>
        <div className="panel-actions">
          <button className="button primary" disabled={replyBusy || !replyToId.trim() || !replyText.trim()}>{replyBusy ? 'Mengantrekan…' : replySettings?.livePosting ? 'Kirim balasan' : 'Catat antrean (live mati)'}</button>
          <button type="button" className={`button ${replySettings?.livePosting ? 'danger-outline' : 'secondary'}`} onClick={() => onToggleReplyLive(!replySettings?.livePosting)}>{replySettings?.livePosting ? 'Matikan live balasan' : 'Aktifkan live balasan'}</button>
          <button type="button" className="button secondary" onClick={onToggleReplyPaused}>{replySettings?.paused ? 'Lanjutkan balasan' : 'Jeda balasan'}</button>
        </div>
      </form>
      {!replySettings?.livePosting && <p className="inline-warning">Live balasan nonaktif: antrean dicatat REQUIRES_LIVE; tidak ada balasan nyata. Scope threads_manage_replies wajib ada di token.</p>}
      {replyQueue.length === 0 ? <Empty>Belum ada balasan.</Empty> : <div className="note-list">{replyQueue.map((item) => <article className="note-card" key={item.id}><div><strong>→ {item.replyToId} · {replyLabels[item.status] ?? item.status}</strong><p>{item.text}</p>{item.mediaId && <p>Media ID: {item.mediaId}</p>}{item.lastError && <p role="alert">{item.lastError}</p>}<small>Percobaan {item.attemptCount} · {formatDate(item.createdAt)}</small>{item.status === 'NEEDS_REVIEW' && <div className="panel-actions"><button className="button secondary" onClick={() => onResolveReply(item, 'REPLIED')}>Tandai terbalas</button><button className="button danger-outline" onClick={() => onResolveReply(item, 'FAILED')}>Tandai gagal</button></div>}</div></article>)}</div>}
    </Panel>
  </>;
}
